import ast, sys
from pathlib import Path
for f in ['core/ground_evidence.py','scripts/prepare_ground_evidence.py','tests/test_ground_evidence_input.py']:
    p=Path('src/human_fall_detection')/f
    src=p.read_text(encoding='utf-8')
    try:
        ast.parse(src, filename=str(p), feature_version=(3,8))
        ok='3.8-OK'
    except SyntaxError as e:
        ok='3.8-SYNTAX-ERR '+str(e)
    mods=set()
    for n in ast.walk(ast.parse(src)):
        if isinstance(n, ast.Import):
            for a in n.names: mods.add(a.name.split('.')[0])
        elif isinstance(n, ast.ImportFrom):
            if n.level: mods.add('relative')
            elif n.module: mods.add(n.module.split('.')[0])
    print(f, ok, sorted(mods))
